def solve(g):
    H=len(g); W=len(g[0]); out=[row[:] for row in g]
    for c in range(W):
        if g[H-1][c]:
            rows=[(r,g[r][c]) for r in range(H) if g[r][c]]
            prev=None
            for r,v in rows:
                start = 0 if prev is None else prev+1
                for rr in range(start,r+1): out[rr][c]=v
                prev=r
    return out

